// Rust: types, calls, raw strings and Unicode
pub fn greet(name: &str) -> String {
    let template = r#"Hello <world> & café 🦀"#;
    format!("{template}, {name}")
}

// TypeScript: generics and template strings
export function greet<T extends string>(name: T): string {
  return `Hello ${name.toUpperCase()}`;
}

export const Greeting = ({ name }: { name: string }) => (
  <div className="greeting">Hello {name}</div>
);

resource "aws_instance" "web" {
  count = 2
  tags = { Name = "web-${var.environment}" }
  user_data = <<-EOT
    echo "hello"
  EOT
}

// Swift: generics and interpolation
func greet<T>(_ name: T) -> String {
    return "Hello \(name)"
}

// Kotlin: interpolation and nullable types
fun greet(name: String?): String {
    return "Hello ${name ?: "world"}"
}

// C#: interpolated strings and methods
public class Greeting {
    public string Hello(string name) => $"Hello {name}";
}
